-- Programme de SEPTEMBRE 2026 de WAKA UP, encode d apres leur calendrier
-- (image : activite/Septembre-waka.jpeg, deposee par Mag le 02/09/2026).
-- Texte en base64 : le presse-papier vers l editeur SQL abime les accents.
--
-- ATTENTION AUX LIEUX. Trois activites ne disent pas OU elles se passent :
--   Les ateliers Karibu (9), Foot en salle (22 et 29), Tricot @ Crazy (24).
--   Un foot en salle n avait pas lieu avenue de Jette, et @ Crazy designe
--   Crazy tisse-reines, pas WAKA UP. Plutot que d inventer une adresse, ces
--   quatre lignes portent 'Lieu a confirmer' et le telephone : envoyer
--   quelqu un a la mauvaise adresse, c est la version 'lieu' du numero invente.
delete from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') and jour >= '2026-09-01' and jour <= '2026-09-30';
select jour, titre, debut, lieu from public.activites where asso = convert_from(decode('V0FLQSBVUA==','base64'),'UTF8') and jour >= '2026-09-01' order by jour, debut;
